// Transport-specific typesupport TU fragment for a json rpc_client.
// Auto-generated by ibmw_gen as an RPC typesupport sidecar.
// The thread-form RpcLoop helper lives here so JSON stays distinct from
// the DDS coroutine form.

namespace my_project {

template <typename SelfT>
inline void _ibmw_json_rpc_client_loop_body_impl(SelfT* self) {
  uint32_t round = 0;

  while (self->running_) {
      {
        ComputeRequest req;
        ComputeResponse rsp;
        // IBMW_RPC_CLIENT_REQUEST_PARAMETER_BUILD_COMPUTE_BEGIN
        static const char* const kOperations[] = {"add", "multiply", "subtract", "unknown_op"};
        req.operation = kOperations[round % 4];
        req.operand_a = 10.0 + round;
        req.operand_b = 3.0;
        // IBMW_RPC_CLIENT_REQUEST_PARAMETER_BUILD_COMPUTE_END

        auto status = ibmw::json::rpc::Call<ComputeRequest, ComputeResponse>(
            self->service_ref_, kServiceName,
            "Compute", req, rsp);

        if (status.OK()) {
          (void)rsp;
          // IBMW_RPC_CLIENT_RESPONSE_PARAMETER_CONSUME_COMPUTE_BEGIN
          MW_LOG(self->GetLogger(), ibmw::common::util::kLogLevelInfo,
                 "[Round {}] Compute({}, {:.1f}, {:.1f}) => code={}, msg='{}', result={:.1f}",
                 round, req.operation, req.operand_a, req.operand_b, rsp.code, rsp.msg, rsp.result);
          // IBMW_RPC_CLIENT_RESPONSE_PARAMETER_CONSUME_COMPUTE_END
        }

        // IBMW_RPC_CLIENT_RETURN_STATUS_HANDLING_COMPUTE_BEGIN
        if (!status.OK()) {
          MW_LOG(self->GetLogger(), ibmw::common::util::kLogLevelWarn, "[Round {}] Compute FAILED => status={}", round, status.Code());
        }
        // IBMW_RPC_CLIENT_RETURN_STATUS_HANDLING_COMPUTE_END

        std::this_thread::sleep_for(std::chrono::milliseconds(500));
      }

    ++round;
    std::this_thread::sleep_for(std::chrono::seconds(1));
  }
}

}  // namespace my_project
